      {
        "id": "ems-operations-031-3",
        "text": "Patient F — facial lacerations suggest critical head injury",
        "isCorrect": false,
        "order": 4,
        "explanation": "START triage is physiological, not anatomical; Patient F passes all RPM criteria and is correctly YELLOW."
      }
